import { Slot } from '@rn-primitives/slot';
import { cva, type VariantProps } from 'class-variance-authority';
import * as React from 'react';
import { Platform, Text as RNText, type Role } from 'react-native';

import { cn } from '@/lib/utils';

// `font-normal` on the base is the one addition to RNR's component, and it is
// load-bearing on native: RN has no cascade, so without a family class every
// unweighted string renders the SYSTEM font while `font-medium`/`font-semibold`
// text renders Inter — the app would be typeset in two fonts at once. The
// plugin maps `font-normal` to Inter_400Regular. Delete the word to get RNR's
// exact base back.
const textVariants = cva(
  cn(
    'text-base font-normal text-foreground',
    Platform.select({
      web: 'select-text',
    }),
  ),
  {
    variants: {
      variant: {
        default: '',
        h1: cn(
          'text-center text-4xl font-extrabold tracking-tight',
          Platform.select({ web: 'scroll-m-20 text-balance' }),
        ),
        h2: cn(
          'border-b border-border pb-2 text-3xl font-semibold tracking-tight',
          Platform.select({ web: 'scroll-m-20 first:mt-0' }),
        ),
        h3: cn('text-2xl font-semibold tracking-tight', Platform.select({ web: 'scroll-m-20' })),
        h4: cn('text-xl font-semibold tracking-tight', Platform.select({ web: 'scroll-m-20' })),
        p: 'mt-3 leading-7 sm:mt-6',
        blockquote: 'mt-4 border-l-2 pl-3 italic sm:mt-6 sm:pl-6',
        code: cn(
          'relative rounded bg-muted px-[0.3rem] py-[0.2rem] font-mono text-sm font-semibold',
        ),
        lead: 'text-xl text-muted-foreground',
        large: 'text-lg font-semibold',
        small: 'text-sm font-medium leading-none',
        muted: 'text-sm text-muted-foreground',
      },
    },
    defaultVariants: {
      variant: 'default',
    },
  },
);

type TextVariantProps = VariantProps<typeof textVariants>;

type TextVariant = NonNullable<TextVariantProps['variant']>;

const ROLE: Partial<Record<TextVariant, Role>> = {
  h1: 'heading',
  h2: 'heading',
  h3: 'heading',
  h4: 'heading',
  blockquote: Platform.select({ web: 'blockquote' as Role }),
  code: Platform.select({ web: 'code' as Role }),
};

const ARIA_LEVEL: Partial<Record<TextVariant, string>> = {
  h1: '1',
  h2: '2',
  h3: '3',
  h4: '4',
};

const TextClassContext = React.createContext<string | undefined>(undefined);

function Text({
  className,
  asChild = false,
  variant = 'default',
  // Cap Dynamic Type so the largest accessibility sizes don't blow out layouts
  // the design system sizes by hand — RNR's Button is `h-10` and its Input
  // `h-10`, and unbounded scaling (iOS AX5 is ~3.6x) clips the label inside
  // them. A deviation from upstream RNR, which sets no cap; callers can still
  // override per-instance. Removing this once was a silent a11y regression that
  // typecheck, lint and the full suite all passed.
  maxFontSizeMultiplier = 1.6,
  ...props
}: React.ComponentProps<typeof RNText> &
  // RNR writes `React.RefAttributes<typeof RNText>` here, which types the ref as
  // the component CLASS rather than an instance of it, so any `ref=` on a Text
  // fails to typecheck. Upstream never trips over it because their demos pass no
  // refs; `post-detail-screen.tsx` does, for screen-reader focus.
  React.RefAttributes<React.ComponentRef<typeof RNText>> &
  TextVariantProps & {
    asChild?: boolean;
  }) {
  const textClass = React.useContext(TextClassContext);
  const Component = asChild ? Slot : RNText;
  return (
    <Component
      className={cn(textVariants({ variant }), textClass, className)}
      role={variant ? ROLE[variant] : undefined}
      aria-level={variant ? ARIA_LEVEL[variant] : undefined}
      maxFontSizeMultiplier={maxFontSizeMultiplier}
      {...props}
    />
  );
}

export { Text, TextClassContext };
export type TextProps = React.ComponentProps<typeof Text>;
